$('switchCalculate').onclick=()=>{try{if(!scopeReady)throw Error('선택 지역 자료를 불러온 뒤 다시 계산하세요.');const fields={sale:'switchSale',debt:'switchDebt',saleCost:'switchSaleCost',extra:'switchExtra',loan:'switchLoan',buyCost:'switchBuyCost'};if(Object.values(fields).some(id=>$(id).value===''))throw Error('자금·대출·비용을 입력하세요. 없는 항목은 0으로 표시하세요.');const b=Engine.switchBudget(Object.fromEntries(Object.entries(fields).map(([k,id])=>[k,+$(id).value])));if(b.budget<=0)throw Error('비용을 제외한 매수 예산이 0 이하입니다.');const years=+$('period').value,bm=Engine.benchmark(data.benchmark.filter(p=>p.region===$('region').value),data.asOf,years),baselineRate=Engine.compare(baselineRows(),data.asOf,years).rate;const candidates=groups().filter(withinArea).filter(g=>!$('dong').value.trim()||g.dong===$('dong').value.trim()).map(g=>({...g,...groupCompare(g,years)})).filter(g=>g.rate!=null&&g.current.price<=b.budget&&!isBaseline(g)).map(g=>({...g,excess:bm==null?null:g.rate-bm,homeDiff:baselineRate==null?null:g.rate-baselineRate,remaining:b.budget-g.current.price,latest:g.latest||g.rows.filter(r=>!r.cancelled&&r.date<=data.asOf).map(r=>r.date).sort().at(-1)})).sort((a,b)=>(b.excess??b.rate)-(a.excess??a.rate));$('switchResult').innerHTML=`<button id="editSwitch" type="button">매도·자금 가정 수정</button><div class="stats"><div>순매도 자금<strong>${b.net.toFixed(2)}억</strong></div><div>비용 제외 매수 예산<strong>${b.budget.toFixed(2)}억</strong></div><div>${baselineRate==null?baselineTitle()+' 비교':baselineTitle()+'보다 더 오른 후보'}<strong>${baselineRate==null?'불가':candidates.filter(g=>g.homeDiff>0).length+'개'}</strong></div></div><p class="meta">${esc($('region').value)} ${esc($('dong').value)} · ${years}년 BM 대비 순. 대표가격은 실거래 중간값이며 실제 매물 호가가 아닙니다. 남는 예산은 대표가격과의 단순 차이로, 추가 비용은 입력값만 반영합니다.</p>`+(candidates.length?'<div class="switch-preview">'+candidates.slice(0,3).map(g=>`<article><h3>${esc(g.name)} · ${g.area}㎡</h3><strong>${g.current.price.toFixed(2)}억</strong><p>예산 ${g.remaining.toFixed(2)}억 남음 · ${esc(cardDifference(g.rate,baselineRate))}</p><button data-switch-detail="${esc(g.key)}">거래 상세</button></article>`).join('')+'</div><details class="method"><summary>후보 가격·거래 근거 모두 보기</summary><div class="table-scroll"><table><thead><tr><th>후보 · 전용면적</th><th>가격 · 남는 예산</th><th>기간 상승률</th><th>'+esc(baselineTitle())+' / BM 대비</th><th>거래 근거</th></tr></thead><tbody>'+candidates.slice(0,10).map(g=>`<tr><td>${esc(g.name)} ${g.area}㎡</td><td>${g.current.price.toFixed(2)}억<small>${g.remaining.toFixed(2)}억 남음</small></td><td>${fmt(g.rate)}</td><td>${g.homeDiff==null?baselineTitle()+' 거래 부족':signed(g.homeDiff)+'%p'} / ${g.excess==null?'BM 자료 부족':signed(g.excess)+'%p'}</td><td>${g.current.count}/${g.previous.count}건 · 최근 ${esc(g.latest||'—')}</td></tr>`).join('')+'</tbody></table></div></details>':'<p>예산과 거래량 조건에 맞는 후보가 없습니다. 추가 예산이나 면적 조건을 조정해보세요.</p>');$('switchError').textContent='';switchContext=resultContext();$('editSwitch').onclick=()=>{$('switchPanel').scrollIntoView?.({behavior:'smooth',block:'start'});$('switchSale').focus?.({preventScroll:true});};$('switchResult').querySelectorAll('[data-switch-detail]').forEach(b=>b.onclick=()=>{detailReturnId='switchResult';selected=b.dataset.switchDetail;detail();$('detail').scrollIntoView({behavior:'smooth',block:'start'});});$('switchResult').scrollIntoView?.({behavior:'smooth',block:'start'});}catch(e){switchContext=null;$('switchResult').innerHTML='';$('switchError').textContent=e.message;}};

