function multiChart(series,dates){
 const values=series.flatMap(s=>s.points.map(p=>p.value)).filter(v=>v!=null);if(!values.length)return '<p class="meta">비교할 거래 자료가 부족합니다.</p>';
 const w=typeof window!=='undefined'&&window.innerWidth<=700?Math.max(220,window.innerWidth-64):850,h=300,l=45,r=12,t=20,b=35,min=Math.min(100,...values),max=Math.max(100,...values),pad=Math.max((max-min)*.12,2),lo=min-pad,hi=max+pad;
 const x=i=>l+i*(w-l-r)/Math.max(1,dates.length-1),y=v=>t+(hi-v)/(hi-lo)*(h-t-b);
 return `<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="시작 기준 100의 아파트·시장 추이, 점선은 시장 기준 추정">${[...([lo,(lo+hi)/2,hi].filter(v=>Math.abs(y(v)-y(100))>18)),100].map(v=>`<line x1="${l}" x2="${w-r}" y1="${y(v)}" y2="${y(v)}" stroke="#dce3ef" ${v===100?'stroke-dasharray="4 4"':''}/><text x="4" y="${y(v)+4}">${v.toFixed(0)}</text>`).join('')}${series.map(s=>{const segments=s.points.slice(1).map((p,j)=>{const prev=s.points[j];return p.value==null||prev.value==null?'':`<path d="M${x(j)},${y(prev.value)}L${x(j+1)},${y(p.value)}" fill="none" stroke="${s.color}" stroke-width="3" ${(p.estimated||prev.estimated)?'stroke-dasharray="6 5"':''}/>`;}).join('');return segments+s.points.map((p,i)=>p.value==null||p.estimated?'':`<circle cx="${x(i)}" cy="${y(p.value)}" r="2.5" fill="${s.color}"><title>${esc(s.label)} ${p.date}: ${p.value.toFixed(1)} · ${s.label.endsWith('시장 BM')?'월 가격지수':'거래창 관측'}</title></circle>`).join('');}).join('')}<text x="${l}" y="${h-5}">${dates[0]}</text><text x="${w-r}" y="${h-5}" text-anchor="end">${dates.at(-1)}</text></svg>`;
}

