function tradeChart(rows,start,end){
 const trades=rows.filter(t=>!t.cancelled&&t.date>=start&&t.date<=end).sort((a,b)=>a.date.localeCompare(b.date)||a.price-b.price);
 if(!trades.length)return '<p class="meta">해당 기간 실제 거래가 없습니다.</p>';
 const w=typeof window!=='undefined'&&window.innerWidth<=700?Math.max(220,window.innerWidth-64):850,h=250,l=50,r=12,top=20,bottom=32,from=Date.parse(start),to=Date.parse(end),values=trades.map(t=>t.price),min=Math.min(...values),max=Math.max(...values),pad=Math.max((max-min)*.12,.15),lo=min-pad,hi=max+pad;
 const x=date=>l+(Date.parse(date)-from)/Math.max(to-from,86400000)*(w-l-r),y=v=>top+(hi-v)/(hi-lo)*(h-top-bottom);
 const days=[...new Set(trades.map(t=>t.date))].map(date=>({date,value:Engine.median(trades.filter(t=>t.date===date).map(t=>t.price))}));
 const lines=days.slice(1).map((p,i)=>{const prev=days[i],gap=(Date.parse(p.date)-Date.parse(prev.date))/86400000;return `<line x1="${x(prev.date)}" y1="${y(prev.value)}" x2="${x(p.date)}" y2="${y(p.value)}" stroke="#8cacee" stroke-width="2" ${gap>90?'stroke-dasharray="5 5"':''}/>`;}).join('');
 return `<svg class="trade-chart" viewBox="0 0 ${w} ${h}" role="group" aria-label="실제 거래가격. 점을 선택하면 계약일 가격 층 표시">${[lo,(lo+hi)/2,hi].map(v=>`<line x1="${l}" x2="${w-r}" y1="${y(v)}" y2="${y(v)}" stroke="#e8edf5"/><text x="2" y="${y(v)+4}">${v.toFixed(1)}억</text>`).join('')}${lines}${trades.map(t=>{const label=`${t.date} · ${t.price.toFixed(2)}억 · ${t.floor==null?'층 미상':t.floor+'층'}`;return `<circle cx="${x(t.date)}" cy="${y(t.price)}" r="4" fill="#234cda" tabindex="0" role="button" aria-label="${esc(label)}" data-trade-label="${esc(label)}"><title>${esc(label)}</title></circle>`;}).join('')}<text x="${l}" y="${h-5}">${start}</text><text x="${w-r}" y="${h-5}" text-anchor="end">${end}</text></svg><p class="trade-info" aria-live="polite">실거래 ${trades.length}건 · 점을 선택하세요.</p><details class="trade-selector"><summary>거래 목록으로 확인</summary><label>계약일 · 가격 · 층<select data-trade-select><option value="">거래 선택</option>${trades.map(t=>{const label=`${t.date} · ${t.price.toFixed(2)}억 · ${t.floor||'층 미상'}층`;return `<option value="${esc(label)}">${esc(label)}</option>`;}).join('')}</select></label></details>`;
}
function bindTradePoints(container){container.querySelectorAll('[data-trade-select]').forEach(select=>select.onchange=()=>{container.querySelector('.trade-info').textContent=select.value||'거래를 선택하세요.';});container.querySelectorAll('[data-trade-label]').forEach(point=>{const show=()=>{container.querySelector('.trade-info').textContent=point.dataset.tradeLabel;};point.onclick=show;point.onfocus=show;point.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();show();}};});}

