async function checkedJSON(url){const r=await fetch(url,{cache:'no-store'});if(!r.ok)throw Error('공식 자료를 불러오지 못했습니다. 잠시 후 지역을 다시 선택하세요.');return r.json();}
async function initSeoul(){const manifest=await checkedJSON('seoul/manifest.json');if(manifest.bootstrapFile&&manifest.bootstrapRevision!==data.revision){if(!/^bootstrap-[a-f0-9]{24}\.json$/.test(manifest.bootstrapFile))throw Error('기본 자료 경로를 확인하세요.');const fresh=await checkedJSON('seoul/'+manifest.bootstrapFile);if(fresh.revision!==manifest.bootstrapRevision||fresh.asOf!==manifest.asOf)throw Error('배포 자료 버전이 다릅니다. 새로고침 후 다시 시도하세요.');load(fresh);}if(manifest.schema!==1||manifest.asOf!==data.asOf||manifest.districts?.length!==25)throw Error('서울 확장 자료의 기준일을 확인하고 있습니다. 현재 자료는 신도림입니다.');seoulManifest=manifest;$('region').value='서울';$('region').disabled=true;$('notice').textContent=`국토교통부 공식 서울 거래 ${manifest.totalTrades.toLocaleString('ko-KR')}건 · ${manifest.fromMonth}~${manifest.throughMonth} · 취소·직거래·토지임대부 제외. 구별 요약을 먼저 받고 선택 단지의 거래 이력만 불러옵니다.`;$('districtScope').innerHTML='<option value="">서울 전체</option>'+manifest.districts.map(d=>`<option value="${esc(d.code)}">${esc(d.name)}</option>`).join('');$('districtScope').value='11530';await loadScope();}
async function loadCatalog(d){if(seoulCatalogs.has(d.code))return;const dataset=datasetVersion,catalog=await checkedJSON('seoul/'+d.file);if(dataset!==datasetVersion)throw Error('자료가 변경되었습니다.');if(catalog.asOf!==data.asOf||catalog.code!==d.code||!Array.isArray(catalog.units))throw Error('지역 자료 기준일이 다릅니다.');for(const u of catalog.units)if(!/^units\/[a-f0-9]{24}\.json$/.test(u.file)||!u.stats?.[1]||u.area<=0)throw Error('지역 요약 형식을 확인하세요.');for(const u of catalog.units)for(const year of [1,3,5,10]){const a=u.stats[year];if(!a)throw Error('기간 요약이 누락되었습니다.');if(Array.isArray(a))u.stats[year]={current:{price:a[0],count:a[1],months:a[2],start:a[10],end:a[11]},previous:{price:a[3],count:a[4],months:a[5],start:a[8],end:a[9]},rate:a[6],annual:a[7]};}seoulCatalogs.set(d.code,catalog);groupVersion++;}
function scopeFailure(error){$('nearbyFlow').hidden=false;$('nearbyFlow').open=true;$('scopePanel').open=true;scopeReady=false;scopePending('자료 연결을 확인하고 있습니다. 위에서 다시 시도하세요.');$('scopeStatus').textContent=error.message;$('scopeRetry').hidden=false;$('purchaseCalculate').disabled=true;clearPurchase();clearSwitchResult();clearHoldingResult();$('results').innerHTML='<p class="meta">공식 자료 연결 후 아파트를 보여드립니다.</p>';}
function scopePending(message){$('openMarketRank').disabled=true;
 $('referenceResult').innerHTML='<p class="meta">'+esc(message)+'</p>';
 for(const id of ['comparisonChart','comparisonLegend','comparisonSelected','comparisonAnswer','comparisonPriceHistory','nearbyLeader','overviewBasis','overviewSources','featuredComparisons'])$(id).innerHTML='';
 $('comparisonMessage').textContent=message;$('count').textContent='—';
 $('listCount').textContent='지역 자료 확인 중';$('recommendation').textContent='';$('referenceHome').disabled=true;$('dong').disabled=true;$('more').hidden=true;for(const id of ['switchCalculate','holdingCalculate'])$(id).disabled=true;
 $('selectionCount').textContent='비교 후보 0/3개';document.querySelector?.('.selection-dock')?.setAttribute('data-active','false');
}
async function loadScope(){if(!seoulManifest)return;scopeReady=false;const version=++scopeVersion,code=$('districtScope').value;$('scopeStatus').textContent='지역 요약을 불러오는 중…';$('scopeRetry').hidden=true;scopePending(scopeTitle()+' 자료를 불러오는 중…');$('purchaseCalculate').disabled=true;clearPurchase();clearSwitchResult();clearHoldingResult();selected=null;comparisonKeys=[];$('results').innerHTML='<p class="meta">선택 지역 자료를 불러오는 중…</p>';$('detail').hidden=true;
 try{const wanted=seoulManifest.districts.filter(d=>!code||d.code===code);for(let i=0;i<wanted.length;i+=4){await Promise.all(wanted.slice(i,i+4).map(loadCatalog));if(version===scopeVersion)$('scopeStatus').textContent=`지역 요약 ${Math.min(i+4,wanted.length)}/${wanted.length}구 불러오는 중…`;}if(version!==scopeVersion)return;scopeReady=true;$('comparisonMessage').textContent='';$('referenceHome').disabled=false;$('dong').disabled=false;$('scopeStatus').textContent=`공식 자료 · ${scopeTitle()} · ${seoulManifest.asOf} 관측 · 서울 ${seoulManifest.totalTrades.toLocaleString('ko-KR')}건`;syncDongChoices();visibleCount=6;render();}catch(e){if(version===scopeVersion){$('scopePanel').open=true;$('scopeStatus').textContent=e.message;$('scopeRetry').hidden=false;scopePending('선택 지역 자료를 불러오지 못했습니다. 위에서 다시 시도하세요.');$('results').innerHTML='<p class="meta">자료 연결 후 이 지역의 아파트를 보여드립니다.</p>';}}finally{if(version===scopeVersion)for(const id of ['purchaseCalculate','switchCalculate','holdingCalculate'])$(id).disabled=!scopeReady;}}
$('dong').onchange=()=>{$('comparisonMessage').textContent='';visibleCount=6;selected=null;comparisonKeys=[];$('detail').hidden=true;render();};
$('scopeRetry').onclick=()=>{const retry=seoulManifest?loadScope():initSeoul();return retry.catch(scopeFailure);};
$('districtScope').onchange=()=>{$('dong').value='';loadScope();};
function syncReferenceChoices(){if(!seoulManifest)return;const current=referenceKey||baselineGroup()?.key||'',matches=groups().filter(g=>withinArea(g)&&(!$('dong').value||g.dong===$('dong').value)&&g.name.includes($('referenceSearch').value.trim())).sort((a,b)=>a.name.localeCompare(b.name)||a.area-b.area),options=matches.slice(0,100),pinned=groups(true).find(g=>g.key===current);if(pinned&&!options.some(g=>g.key===current))options.unshift(pinned);$('referenceHome').innerHTML=options.map(g=>`<option value="${esc(g.key)}">${esc(g.name)} · ${g.area}㎡ · ${esc(g.district)} ${esc(g.dong)}</option>`).join('');$('referenceHome').value=current;$('referenceMatches').textContent=matches.length>100?'검색 결과가 많습니다. 단지명을 입력하면 더 좁힐 수 있습니다.':'';}
$('referenceSearch').oninput=syncReferenceChoices;
async function ensureRaw(g){if(g.rows.length||!g.file)return g.rows;if(seoulRows.has(g.key))return seoulRows.get(g.key);if(seoulRequests.has(g.key))return seoulRequests.get(g.key);const dataset=datasetVersion,request=checkedJSON('seoul/'+g.file).then(d=>{if(dataset!==datasetVersion)throw Error('자료가 변경되었습니다.');if(d.asOf!==data.asOf||d.key!==g.key||!Array.isArray(d.rows)||!d.rows.length||d.rows.some(r=>!(r.price>0)||!/^\d{4}-\d{2}-\d{2}$/.test(r.date)))throw Error('단지 거래 자료를 확인하세요.');seoulRows.set(g.key,d.rows);groupVersion++;return d.rows;}).catch(e=>{seoulFailures.add(g.key);throw e;}).finally(()=>seoulRequests.delete(g.key));seoulRequests.set(g.key,request);return request;}
$('referenceHome').onchange=async()=>{const request=++referenceVersion,dataset=datasetVersion,scope=scopeVersion,key=$('referenceHome').value,g=groups(true).find(g=>g.key===key);if(!g)return;try{await ensureRaw(g);if(request!==referenceVersion||dataset!==datasetVersion||scope!==scopeVersion)return;referenceKey=key;$('switchSale').value='';selected=null;comparisonKeys=[];render();}catch(e){$('scopeStatus').textContent=e.message;syncReferenceChoices();}};
function addChartReadout(container,series,dates){const id='comparisonReadout';container.innerHTML+=`<details class="chart-values"><summary>날짜별 수치 보기</summary><label class="chart-scrubber">날짜 선택<input id="${id}" type="range" min="0" max="${dates.length-1}" value="${dates.length-1}" step="1"></label><small>막대를 좌우로 움직여 날짜별 값을 확인하세요.</small><p id="comparisonPoint" class="chart-point" aria-live="polite"></p></details>`;const show=()=>{const i=+$(id).value;$(id).setAttribute?.('aria-valuetext',dates[i]);$('comparisonPoint').textContent=dates[i]+' · '+series.map(s=>{const p=s.points[i];return s.label+': '+(p.value==null?'자료 없음':p.value.toFixed(1)+(p.estimated?' (시장 기준 추정)':' (관측)'));}).join(' / ');};$(id).oninput=show;show();}

let holdingArchiveLoaded=false,holdingArchiveRequest=null;
$('holdingPanel').ontoggle=async()=>{if(!$('holdingPanel').open||!seoulManifest||holdingArchiveLoaded)return;const version=datasetVersion;$('holdingStatus').textContent='보유기간 비교 자료를 불러오는 중…';try{if(!holdingArchiveRequest)holdingArchiveRequest=checkedJSON('seoul/sindorim.json');const archive=validate(await holdingArchiveRequest);if(version!==datasetVersion||archive.asOf!==data.asOf)return;data.transactions=archive.transactions;groupVersion++;holdingArchiveLoaded=true;holdingLoad();$('holdingStatus').textContent='';}catch(e){$('holdingHint').textContent=e.message;$('holdingStatus').textContent=e.message;holdingArchiveRequest=null;}};

// Intent opens the relevant tool; inputs/results remain intact when folded.
function openFlow(id,target=id){$(id).hidden=false;$(id).open=true;$(target).scrollIntoView({behavior:'smooth',block:'start'});$(id).querySelector?.('summary')?.focus?.({preventScroll:true});}
$('openPurchase').onclick=()=>openFlow('purchaseFlow');
$('openNearby').onclick=()=>{$('scopeUseForPurchase').hidden=true;openFlow('nearbyFlow');};
$('scopeUseForPurchase').onclick=()=>{$('scopePanel').open=false;$('scopeUseForPurchase').hidden=true;openFlow('purchaseFlow');$('buyOwn').focus?.({preventScroll:true});};
$('purchaseScope').onclick=()=>{$('scopeUseForPurchase').hidden=false;openFlow('nearbyFlow');$('scopePanel').open=true;$('districtScope').focus?.();};
['heroPeriod','nearbyPeriod','chartPeriod','detailPeriod','marketRankPeriod'].forEach(id=>$(id).onchange=()=>{$('period').value=$(id).value;visibleCount=6;render();});
$('openFunding').onclick=()=>{$('fundingDetails').open=true;$('buyLtv').focus?.();};
function fundingSummary(){const ltv=$('buyLtv').value||'—',rate=$('buyInterest').value||'—',years=$('buyYears').value||'—';$('fundingSummary').textContent=`LTV ${ltv}% · 금리 ${rate}% · ${years}년 가정`;}

for(const [panel,button] of [['purchaseFlow','openPurchase'],['nearbyFlow','openNearby'],['marketRankFlow','openMarketRank']])$(panel).ontoggle=()=>{$(button).setAttribute?.('aria-expanded',String($(panel).open));if(!$(panel).open){$(panel).hidden=true;$(button).focus?.({preventScroll:true});}};

// Seoul-wide exploration loads published district summaries only after explicit intent.
$('openMarketRank').onclick=()=>{openFlow('marketRankFlow');loadMarketRank();};
$('marketRankRetry').onclick=loadMarketRank;
$('marketRankMore').onclick=()=>{marketRankVisible+=6;renderMarketRank();};
document.querySelectorAll?.('[data-rank-side]').forEach(b=>b.onclick=()=>{marketRankSide=b.dataset.rankSide;marketRankVisible=6;renderMarketRank();});
$('marketRankArea').onchange=()=>{$('areaScope').value=$('marketRankArea').value;marketRankVisible=6;visibleCount=6;render();};
async function loadMarketRank(){
 if(marketRankReady){renderMarketRank();return;}
 if(marketRankRequest)return marketRankRequest;
 const version=++marketRankVersion,dataset=datasetVersion,manifest=seoulManifest;
 $('marketRankResults').innerHTML='';$('marketRankMore').hidden=true;$('marketRankRetry').hidden=true;$('marketRankStatus').setAttribute?.('data-ready','false');$('marketRankStatus').textContent='서울 25개구 자료를 불러오고 있어요…';
 marketRankRequest=(async()=>{try{
  if(!manifest)throw Error('공식 서울 자료 연결 후 다시 시도하세요.');
  for(let i=0;i<manifest.districts.length;i+=4){await Promise.all(manifest.districts.slice(i,i+4).map(loadCatalog));if(version!==marketRankVersion||dataset!==datasetVersion)return;$('marketRankStatus').textContent=`서울 자료 ${Math.min(i+4,25)}/25개구 연결 중…`;}
  if(version!==marketRankVersion||dataset!==datasetVersion)return;
  if(!manifest.districts.every(d=>seoulCatalogs.has(d.code)))throw Error('서울 전체 자료가 아직 연결되지 않았습니다.');
  if(!scopeReady)await loadScope();
  if(version!==marketRankVersion||dataset!==datasetVersion)return;
  marketRankReady=true;render();
 }catch(e){if(version===marketRankVersion){marketRankReady=false;$('marketRankStatus').textContent='서울 전체를 연결하지 못해 순위를 표시하지 않았어요. 다시 불러올 수 있어요.';$('marketRankRetry').hidden=false;$('marketRankResults').innerHTML='';$('marketRankMore').hidden=true;}}
 finally{if(version===marketRankVersion)marketRankRequest=null;}})();return marketRankRequest;
}
function renderMarketRank(){
 document.querySelectorAll?.('[data-rank-side]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.rankSide===marketRankSide)));
 $('marketRankPeriod').value=$('period').value;$('marketRankArea').value=$('areaScope').value;
 if(!marketRankReady||!seoulManifest)return;
 const context=[datasetVersion,$('period').value,$('areaScope').value].join('|');if(context!==marketRankContext){marketRankVisible=6;marketRankContext=context;}
 const years=+$('period').value,bm=Engine.benchmark(data.benchmark.filter(p=>p.region==='서울'),data.asOf,years),all=groups(true).filter(g=>g.region==='서울'&&withinArea(g)).map(g=>({...g,...groupCompare(g,years)})),ranked=Engine.marketRanks(all,bm,data.asOf,marketRankSide);
 $('marketRankBenchmark').textContent=`같은 ${years}년 서울 시장 ${fmt(bm)}`;
 $('marketRankScope').textContent=`서울 전체 · ${$('areaScope').value==='all'?'전체 면적':'전용 75~95㎡'} · ${years}년`;
 $('marketRankStatus').textContent='';$('marketRankStatus').setAttribute?.('data-ready','true');$('marketRankRetry').hidden=true;

 $('marketRankBasis').textContent=`${data.asOf} 관측 · 서울 25개구 전체 연결. 조건에 맞는 ${marketRankSide==='high'?'상승률 상위':'상승률 하위'} 표본 ${ranked.length.toLocaleString('ko-KR')}개 중 ${Math.min(marketRankVisible,ranked.length)}개 표시. 가격은 실거래 대표가격이며 현재 매물 호가가 아닙니다. 주변 목록의 검색·가격 필터와 별개입니다.`;
 $('marketRankResults').innerHTML=ranked.length?ranked.slice(0,marketRankVisible).map((g,i)=>`<article class="card rank-card" data-rank-key="${esc(g.key)}"><span class="rank-position">${i+1}위${isBaseline(g)?' · 비교 기준':''}</span><h3 class="rank-location">${esc(g.district)} ${esc(g.dong)}</h3><p class="rank-apartment">${esc(g.name)} · 전용 ${g.area}㎡</p><p class="rank-gap ${marketRankSide}">서울 대비 <strong>${signed(g.excess)}%p</strong></p><div class="row"><span class="price">${g.current.price.toFixed(2)}억</span><span class="return">${fmt(g.rate)}</span></div><details class="card-basis"><summary>가격·거래 근거</summary><p>${g.current.months}개월 거래창 · 현재 ${g.current.count}건 / 과거 ${g.previous.count}건 · 최근 계약 ${esc(g.latest)}</p><p>같은 ${years}년 서울 ${fmt(bm)}와 비교한 누적 상승률 차이입니다. 미래 수익 예측이 아닙니다.</p></details><div class="card-actions"><button data-rank-compare="${esc(g.key)}" aria-pressed="${comparisonKeys.includes(g.key)}">${comparisonKeys.includes(g.key)?'비교에서 빼기':'그래프로 비교'}</button><button data-rank-detail="${esc(g.key)}">거래 상세</button></div></article>`).join(''):`<p class="empty">${bm==null?'이 기간의 서울 시장 지수가 없어 비교할 수 없어요.':'이 기간·면적·거래 기준에 맞는 표본이 없어요. 기간이나 면적을 바꿔보세요.'}</p>`;
 $('marketRankMore').hidden=marketRankVisible>=ranked.length;$('marketRankMore').textContent=`아파트 더 보기 · ${Math.max(0,ranked.length-marketRankVisible)}개 남음`;
 $('marketRankResults').querySelectorAll('[data-rank-compare]').forEach(b=>b.onclick=()=>toggleComparison(b.dataset.rankCompare,'marketRank'));
 $('marketRankResults').querySelectorAll('[data-rank-detail]').forEach(b=>b.onclick=()=>{detailReturnId='marketRankResults';selected=b.dataset.rankDetail;detail();$('detail').scrollIntoView({behavior:'smooth',block:'start'});});
}
